import gurobipy as gp
from gurobipy import GRB
import json

slots = [
    {
        "slot_id": 1,
        "quantity": 1,
        "candidates": [
            {"product_id": "dda780bf", "price": 249.9}
        ]
    },
    {
        "slot_id": 2,
        "quantity": 1,
        "candidates": [
            {"product_id": "4dc5e9f8", "price": 429.0}
        ]
    },
    {
        "slot_id": 3,
        "quantity": 1,
        "candidates": [
            {"product_id": "0d4a99f7", "price": 899.0}
        ]
    },
    {
        "slot_id": 4,
        "quantity": 1,
        "candidates": [
            {"product_id": "f24c7623", "price": 429.9}
        ]
    },
    {
        "slot_id": 5,
        "quantity": 1,
        "candidates": [
            {"product_id": "bfaea6ad", "price": 229.0}
        ]
    }
]

env = gp.Env(empty=True)
env.setParam("OutputFlag", 0)
env.start()

model = gp.Model("wardrobe", env=env)

x = {}
for slot in slots:
    sid = slot["slot_id"]
    for cand in slot["candidates"]:
        x[(sid, cand["product_id"])] = model.addVar(
            vtype=GRB.BINARY, name=f"x_{sid}_{cand['product_id']}"
        )

model.update()

for slot in slots:
    sid = slot["slot_id"]
    model.addConstr(
        gp.quicksum(x[(sid, c["product_id"])] for c in slot["candidates"]) == 1,
        name=f"select_one_{sid}"
    )

model.setObjective(
    gp.quicksum(
        x[(slot["slot_id"], cand["product_id"])] * cand["price"] * slot["quantity"]
        for slot in slots
        for cand in slot["candidates"]
    ),
    GRB.MINIMIZE
)

model.optimize()

if model.Status == GRB.OPTIMAL:
    selected = []
    total = 0.0
    for slot in slots:
        sid = slot["slot_id"]
        for cand in slot["candidates"]:
            if x[(sid, cand["product_id"])].X > 0.5:
                selected.append({
                    "slot_id": sid,
                    "product_id": cand["product_id"],
                    "quantity": slot["quantity"],
                    "unit_price": cand["price"]
                })
                total += cand["price"] * slot["quantity"]
    print(json.dumps({
        "status": "optimal",
        "selected_products": selected,
        "total_price": total
    }))
else:
    print(json.dumps({"status": "infeasible", "selected_products": [], "total_price": None}))
